import asyncio, sys, json
from playwright.async_api import async_playwright
EXE="/pw-browsers/chromium_headless_shell-1208/chrome-linux/headless_shell"
MOBILE = len(sys.argv)>1 and sys.argv[1]=='m'
LIGHT = '--light' in sys.argv
TAG = ('m' if MOBILE else 'd')+('l' if LIGHT else '')
TXT = "[Intro]\nYeah yeah\n\n[Hook: Chelly]\nWe up all night\nLights on **bright**\n\n[Verse 1: Chelly]\nFirst line here\nSecond line here\n\n[Hook: Sav]\nWe up all night\nLights on **bright**\n\n[Verse 2: Sav]\nThird line\nFourth line\n\n[Outro]\nBye"
ok=0; bad=0
def chk(name, cond, extra=''):
    global ok, bad
    if cond: ok+=1; print('PASS', name, extra)
    else: bad+=1; print('FAIL', name, extra)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=EXE)
        ctx = await b.new_context(**(p.devices['iPhone 13'] if MOBILE else {'viewport':{'width':1400,'height':850}}))
        pg = await ctx.new_page(); pg.on('pageerror', lambda e: print('PAGEERR', e))
        await pg.goto('http://localhost:3000/'); await pg.evaluate("(l)=>{localStorage.setItem('treesh_whatsnew_off','true'); localStorage.setItem('treesh_eco_seen','1'); localStorage.setItem('treesh_profile', JSON.stringify({nickname:'Tester',birthday:'2000-01-01'})); localStorage.removeItem('treesh_lsv_group'); if(l) localStorage.setItem('treesh_theme', JSON.stringify('light'));}", LIGHT); await pg.reload(); await pg.wait_for_timeout(3500)
        # song editor: rhymes + find lyrics in the format bar
        sid = await pg.evaluate("()=>{ const s=SONGS.find(x=>(x.lyrics||[]).length>5); openLyricSync(s.id); return s.id; }"); await pg.wait_for_timeout(1500)
        await pg.evaluate("()=>{ if(state.ls&&state.ls.mode!=='write') lsSetMode('write'); }"); await pg.wait_for_timeout(600)
        r = await pg.evaluate("()=>{ const bar=document.querySelector('[data-testid=ls-tools-bar]'); const k=[...bar.children].map(x=>x.dataset.testid); const mk=document.querySelector('[data-testid=ls-markup-row]'); return {k, n:document.querySelectorAll('[data-testid=ls-find-online]').length, nr:document.querySelectorAll('[data-testid=ls-rhyme-toggle]').length, mkH:Math.round(mk.getBoundingClientRect().height), inert:mk.hasAttribute('inert'), ed:Math.round(document.querySelector('.lsx-ed').getBoundingClientRect().height)} }")
        chk('tools row order rhymes, find, verses, markup', r['k'][:5]==['ls-rhyme-toggle','ls-find-online','ls-sections-toggle','ls-verses-open','ls-markup-toggle'] and r['n']==1 and r['nr']==1, r)
        chk('markup row closed by default', r['mkH']<=1 and r['inert'], r)
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_song.png')
        await pg.locator('[data-testid=ls-markup-toggle]').click(); await pg.wait_for_timeout(500)
        r2 = await pg.evaluate("()=>{ const mk=document.querySelector('[data-testid=ls-markup-row]'); return {h:Math.round(mk.getBoundingClientRect().height), inert:mk.hasAttribute('inert'), exp:document.querySelector('[data-testid=ls-markup-toggle]').getAttribute('aria-expanded'), bold:document.querySelector('[data-testid=ls-md-bold]').getBoundingClientRect().height} }")
        chk('markup expands with tools', r2['h']>30 and not r2['inert'] and r2['exp']=='true' and r2['bold']>20, r2)
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_song_mk.png')
        await pg.locator('[data-testid=ls-markup-toggle]').click(); await pg.wait_for_timeout(500)
        await pg.locator('[data-testid=ls-sections-toggle]').click(); await pg.wait_for_timeout(500)
        r3 = await pg.evaluate("()=>({sec:Math.round(document.querySelector('[data-testid=ls-sections-row]').getBoundingClientRect().height), mk:Math.round(document.querySelector('[data-testid=ls-markup-row]').getBoundingClientRect().height), chip:!!document.querySelector('[data-testid=ls-sections-row] [data-testid=ls-tag-Hook]')})")
        chk('sections opens and closes markup', r3['sec']>40 and r3['mk']<=1 and r3['chip'], r3)
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_song_sec.png')
        await pg.locator('[data-testid=ls-tag-Hook]').click(); await pg.wait_for_timeout(300)
        chk('section chip inserts tag', await pg.evaluate("()=>document.getElementById('ls-write').value.indexOf('[Hook]')>=0"))
        await pg.locator('[data-testid=ls-tips-toggle]').click(); await pg.wait_for_timeout(300)
        chk('tips toggle shows tips', await pg.evaluate("()=>!document.getElementById('ls-tips-panel').classList.contains('hidden')"))
        await pg.locator('[data-testid=ls-sections-toggle]').click(); await pg.wait_for_timeout(500)
        chk('sections collapses', await pg.evaluate("()=>document.querySelector('[data-testid=ls-sections-row]').getBoundingClientRect().height<=1"))
        await pg.locator('[data-testid=ls-markup-toggle]').click(); await pg.wait_for_timeout(400)
        await pg.locator('[data-testid=ls-markup-toggle]').click(); await pg.wait_for_timeout(400)
        chk('markup collapses again', await pg.evaluate("()=>document.querySelector('[data-testid=ls-markup-row]').getBoundingClientRect().height<=1"))
        r0 = await pg.evaluate("()=>state.lsRhymesOn")
        await pg.locator('[data-testid=ls-rhyme-toggle]').click(); await pg.wait_for_timeout(400)
        chk('rhymes toggles', await pg.evaluate("(r0)=>state.lsRhymesOn===!r0 && document.querySelector('[data-testid=ls-rhyme-toggle]').getAttribute('aria-checked')===String(!r0) && !!document.querySelector('[data-testid=ls-tools-bar] [data-testid=ls-rhyme-toggle]')", r0))
        await pg.locator('[data-testid=ls-rhyme-toggle]').click(); await pg.wait_for_timeout(300)
        await pg.evaluate("()=>{ state.ls.dirty=false; closeLS(); }"); await pg.wait_for_timeout(600)
        # blank draft with sections
        await pg.evaluate("()=>{ openLyricBlank(null); state.ls.title='Verse test'; }"); await pg.wait_for_timeout(1200)
        await pg.evaluate("(t)=>{ const ta=document.getElementById('ls-write'); ta.value=lsMdToTa(t); ta.dispatchEvent(new Event('input',{bubbles:true})); }", TXT); await pg.wait_for_timeout(300)
        chk('verses badge counts sections', (await pg.locator('[data-testid=ls-verses-count]').inner_text())=='6')
        await pg.locator('[data-testid=ls-verses-open]').click(); await pg.wait_for_timeout(900)
        chk('panel open', await pg.locator('[data-testid=ls-verses-panel]').count()==1)
        chk('6 cards', await pg.locator('#lsv .lsv-card').count()==6)
        chk('summary', '6 sections' in (await pg.locator('[data-testid=lsv-summary]').inner_text()))
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_panel.png')
        chk('dupe hint for Hook', await pg.locator('[data-testid=lsv-dupe-0]').count()==1)
        await pg.locator('[data-testid=lsv-dupe-0]').click(); await pg.wait_for_timeout(500)
        chk('merge sheet', await pg.locator('[data-testid=lsv-sheet-merge]').count()==1)
        chk('merge label suggested', await pg.locator('[data-testid=lsv-merge-label]').input_value()=='Hook: Chelly & Sav', await pg.locator('[data-testid=lsv-merge-label]').input_value())
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_merge.png')
        await pg.locator('[data-testid=lsv-merge-one]').click(); await pg.wait_for_timeout(500)
        st = await pg.evaluate("()=>state.lsv.blocks.map(b=>[b.label,lsvLines(b).length])")
        chk('merge into one: 5 sections, identical hook not doubled', len(st)==5 and st[1]==['Hook: Chelly & Sav',2], st)
        await pg.locator('[data-testid=lsv-undo]').click(); await pg.wait_for_timeout(400)
        chk('undo restores 6', await pg.evaluate("()=>state.lsv.blocks.length")==6)
        await pg.locator('[data-testid=lsv-sel-clear]').click(); await pg.wait_for_timeout(200)
        await pg.locator('[data-testid=lsv-select-1]').click(); await pg.locator('[data-testid=lsv-select-3]').click(); await pg.wait_for_timeout(300)
        chk('selbar 2 selected', (await pg.locator('[data-testid=lsv-sel-count]').inner_text())=='2')
        await pg.locator('[data-testid=lsv-merge]').click(); await pg.wait_for_timeout(400)
        await pg.locator('[data-testid=lsv-merge-label-only]').click(); await pg.wait_for_timeout(400)
        st = await pg.evaluate("()=>state.lsv.blocks.map(b=>b.label)")
        chk('share one label keeps 6 and renames both', len(st)==6 and st[1]==st[3]=='Hook: Chelly & Sav', st)
        await pg.locator('[data-testid=lsv-add-line]').click(); await pg.wait_for_timeout(300)
        await pg.locator('[data-testid=lsv-line-input]').fill('(Ayy)'); await pg.locator('[data-testid=lsv-line-add]').click(); await pg.wait_for_timeout(400)
        st = await pg.evaluate("()=>[lsvLines(state.lsv.blocks[1]).slice(-1)[0], lsvLines(state.lsv.blocks[3]).slice(-1)[0], lsvLines(state.lsv.blocks[2]).slice(-1)[0]]")
        chk('add a line to 2 selected only', st[0]=='(Ayy)' and st[1]=='(Ayy)' and st[2]!='(Ayy)', st)
        # edit label + lines in a card
        await pg.locator('[data-testid=lsv-label-5]').fill('Outro: Chelly'); await pg.locator('[data-testid=lsv-lines-5]').fill('Bye now\nSee ya')
        chk('card edits in model', await pg.evaluate("()=>state.lsv.blocks[5].label==='Outro: Chelly' && lsvLines(state.lsv.blocks[5]).length===2"))
        await pg.locator('[data-testid=lsv-group-artist]').click(); await pg.wait_for_timeout(500)
        lanes = await pg.locator('#lsv .lsv-lane').count()
        chk('group by artist lanes', lanes>=3, lanes)
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_artist.png')
        await pg.locator('[data-testid=lsv-group-order]').click(); await pg.wait_for_timeout(300)
        await pg.locator('[data-testid=lsv-move-right-0]').click(); await pg.wait_for_timeout(300)
        chk('move right', await pg.evaluate("()=>state.lsv.blocks[1].label==='Intro'"))
        await pg.locator('[data-testid=lsv-preview-toggle]').click(); await pg.wait_for_timeout(500)
        chk('preview shows', await pg.locator('[data-testid=lsv-preview]').count()==1)
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_preview.png')
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(400)
        chk('escape with changes asks to save', await pg.locator('[data-testid=lsv-sheet-leave]').count()==1)
        await pg.locator('[data-testid=lsv-leave-save]').click(); await pg.wait_for_timeout(800)
        txt = await pg.evaluate("()=>lsTaToMd(document.getElementById('ls-write').value)")
        chk('saved into editor', '[Hook: Chelly & Sav]' in txt and '(Ayy)' in txt and txt.index('[Intro]')>txt.index('[Hook: Chelly & Sav]') and '**bright**' in txt, txt[:80].replace('\n','|'))
        chk('panel closed', await pg.locator('[data-testid=ls-verses-panel]').count()==0)
        chk('draft saved', await pg.evaluate("()=>(state.lyricDrafts||[]).some(d=>JSON.stringify(d).indexOf('Chelly & Sav')>=0)"))
        await pg.screenshot(path=f'/tmp/lsv_{TAG}_after.png')
        await b.close()
    print('RESULT', ok, 'pass', bad, 'fail')
asyncio.run(main())
